module signal_generator(
    input clk,
    input rst_n,
    output reg [4:0] wave
);

    reg state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= 0;
            wave <= 0;
        end
        else begin
            case (state)
                0: begin
                    if (wave != 31)
                        wave <= wave + 1;
                    else
                        state <= 1;
                end
                1: begin
                    if (wave != 0)
                        wave <= wave - 1;
                    else
                        state <= 0;
                end
            endcase
        end
    end

endmodule
